var OT_LOG = '[OptanonWrapper]';
var OT_DEBUG = false;
function otLog() { if (OT_DEBUG) console.debug.apply(console, arguments); }

var NON_ESSENTIAL = ['C0002', 'C0003', 'C0004'];
var otDeferredTimer = null;

// Called by OneTrust on every page load and every consent change.
function OptanonWrapper() {
 // On first run, capture the current consent state as a baseline.
 if (typeof OptanonWrapperCount === 'undefined') {
 OptanonWrapperCount = '';
 otIniGrps = OnetrustActiveGroups;
 otLog(OT_LOG, 'init', otIniGrps);

 // Stale cookie cleanup: if non-essential categories are already denied
 // (returning visitor who rejected previously), delete leftover cookies
 // once per session so stale identifiers don't persist across visits.
 staleCookieCleanup();
 return;
 }

 // Diff: which groups were in the baseline but are no longer active?
 // e.g. user had C0001,C0002,C0004 → now has C0001 → revoked = [C0002, C0004]
 var curr = OnetrustActiveGroups.split(',').filter(Boolean);
 var revoked = otIniGrps.split(',').filter(Boolean)
 .filter(function(id) { return curr.indexOf(id) === -1; });

 if (revoked.length === 0) {
 otIniGrps = OnetrustActiveGroups;
 return;
 }

 deleteCookiesForGroups(revoked, 'revoked');

 // Cancel any previously scheduled deferred pass before starting a new one.
 // Only done here (not at the top of the function) because OneTrust can call
 // OptanonWrapper multiple times in quick succession for the same consent
 // action (e.g. save + banner close). Those no-op re-entries (revoked=[])
 // exit early above and must not cancel a valid pending timer.
 if (otDeferredTimer) {
 clearTimeout(otDeferredTimer);
 otDeferredTimer = null;
 }

 // Deferred second pass: in-page SDKs (RUM, intent data, etc.) can re-write
 // cookies after the first sweep on the same navigation. We recompute which
 // groups are still denied at execution time so a quick reject → re-accept
 // within the window doesn't incorrectly delete re-approved cookies.
 otDeferredTimer = setTimeout(function() {
 otDeferredTimer = null;
 var active = OnetrustActiveGroups.split(',').filter(Boolean);
 var stillRevoked = NON_ESSENTIAL.filter(function(id) {
 return active.indexOf(id) === -1;
 });
 if (stillRevoked.length > 0) {
 deleteCookiesForGroups(stillRevoked, 'revoked (deferred)');
 }
 }, 3000);

 // Update baseline so the next consent change diffs correctly.
 otIniGrps = OnetrustActiveGroups;
}

// One-time sweep for stale cookies from a prior session where consent was granted
// but is now denied. Runs at most once per browser session (sessionStorage flag).
function staleCookieCleanup() {
 try {
 if (sessionStorage.getItem('ot_cleanup_done')) return;
 } catch (e) { /* sessionStorage unavailable (privacy mode) — proceed with cleanup */ }

 var curr = OnetrustActiveGroups.split(',').filter(Boolean);
 var denied = NON_ESSENTIAL.filter(function(id) { return curr.indexOf(id) === -1; });

 if (denied.length === 0) return;

 var count = deleteCookiesForGroups(denied, 'stale cleanup');

 // Set flag if inventory was successfully read (count >= 0).
 // -1 means GetDomainData was unavailable — retry next page load.
 if (count >= 0) {
 try { sessionStorage.setItem('ot_cleanup_done', '1'); } catch (e) {}
 }
}

// Shared: fetch OneTrust inventory and delete cookies for the given group IDs.
// Returns deleted count (>= 0) on success, or -1 if inventory was unavailable.
function deleteCookiesForGroups(groupIds, reason) {
 otLog(OT_LOG, reason, groupIds);

 var groups;
 try {
 groups = Optanon.GetDomainData().Groups;
 } catch (e) {
 otLog(OT_LOG, 'GetDomainData unavailable');
 return -1;
 }
 if (!groups || !groups.length) return 0;

 var seen = {};
 var deleted = [];

 function queueCookie(name) {
 if (seen[name]) return;
 seen[name] = 1;
 eraseCookie(name);
 deleted.push(name);
 }

 for (var i = 0; i < groups.length; i++) {
 var g = groups[i];

 if (!g.CustomGroupId || groupIds.indexOf(g.CustomGroupId) === -1) continue;

 // First-party cookies: directly under the group
 if (g.Cookies) {
 for (var j = 0; j < g.Cookies.length; j++) {
 queueCookie(g.Cookies[j].Name);
 }
 }

 // Host cookies: grouped by third-party host under this category.
 // These are still first-party cookies on .braze.com in most cases;
 // true third-party cookies can't be deleted (same-origin policy).
 if (g.Hosts) {
 for (var h = 0; h < g.Hosts.length; h++) {
 var host = g.Hosts[h];
 if (host.Cookies) {
 for (var k = 0; k < host.Cookies.length; k++) {
 queueCookie(host.Cookies[k].Name);
 }
 }
 }
 }
 }

 otLog(OT_LOG, reason, 'deleted', deleted.length, 'cookies', deleted);
 return deleted.length;
}

// Expire a first-party cookie by setting Max-Age=-99999999 across all
// domain/path combinations. We try the hostname (www.braze.com), the apex
// (braze.com), and the dotted apex (.braze.com) because we don't know
// which domain the cookie was originally set on.
function eraseCookie(name) {
 var hostname = window.location.hostname;
 var domains = [hostname];
 var dot = hostname.indexOf('.');
 if (dot > -1) {
 var apex = hostname.substring(dot + 1);
 if (apex !== hostname) {
 domains.push(apex);
 domains.push('.' + apex);
 }
 }

 function expire(path) {
 var base = name + '=; Max-Age=-99999999; Path=' + path;
 document.cookie = base + ';';
 // Retry with Secure + SameSite=None for cookies originally set with those attributes
 document.cookie = base + '; Secure; SameSite=None;';
 for (var i = 0; i < domains.length; i++) {
 document.cookie = base + ';Domain=' + domains[i] + ';';
 document.cookie = base + ';Domain=' + domains[i] + '; Secure; SameSite=None;';
 }
 }

 expire('/');

 // Also clear matching localStorage entry (some vendors use both)
 try { localStorage.removeItem(name); } catch (e) {}

 // Walk the current URL path hierarchy (/en-us/solutions -> /en-us, /en-us/solutions)
 var parts = window.location.pathname.split('/');
 for (var i = 0; i < parts.length; i++) {
 if (parts[i]) {
 var p = parts.slice(0, i + 1).join('/');
 expire(p);
 expire(p + '/');
 }
 }
}
